// Validate and normalize Fireflies webhook event.
const body = $json.body ?? $json;
const meetingId = body.meetingId ?? body.meeting_id ?? body.transcriptId ?? body.transcript_id;
const eventType = body.eventType ?? body.event ?? '';
if (typeof meetingId !== 'string' || !meetingId.trim()) {
  throw new Error('Fireflies webhook did not include meetingId/meeting_id. Inspect the actual webhook payload.');
}
const normalizedEvent = String(eventType).toLowerCase();
if (normalizedEvent && !(normalizedEvent.includes('transcrib') || normalizedEvent.includes('summar'))) {
  return [{ json: { ignored: true, meetingId, eventType } }];
}
return [{ json: {
  ignored: false,
  meetingId: meetingId.trim(),
  eventType: eventType || 'unspecified',
  clientReferenceId: body.clientReferenceId ?? body.client_reference_id ?? '',
  webhookTimestamp: body.timestamp ?? null,
  receivedAt: new Date().toISOString(),
  meetingDate: body.meetingDate ?? body.meeting_date ?? ''
} }];

// Shared normalizer for Fireflies and the manual chat test trigger.
const payload = $json;

if (payload.data?.transcript) {
  if (Array.isArray(payload.errors) && payload.errors.length) {
    throw new Error('Fireflies GraphQL error: ' + payload.errors.map(e => e.message).join('; '));
  }
  const transcript = payload.data.transcript;
  if (!Array.isArray(transcript.sentences)) {
    throw new Error('Fireflies response has no transcript.sentences. Check transcript ID and API permissions.');
  }
  const sentences = transcript.sentences.filter(s => typeof s.text === 'string' && s.text.trim());
  const transcriptText = sentences.map(s => `${s.speaker_name || 'Speaker'}: ${s.text.trim()}`).join('\n');
  if (transcriptText.trim().length < 20) throw new Error('Retrieved transcript is empty or too short to analyse.');
  const event = $('Validate Fireflies Event').first().json;
  return [{ json: {
    meetingId: transcript.id || event.meetingId,
    transcriptId: transcript.id || event.meetingId,
    meetingTitle: transcript.title || 'Untitled meeting',
    meetingDate: event.meetingDate || 'Unknown',
    transcript: transcriptText,
    source: 'Fireflies',
    summaryOverview: transcript.summary?.overview || '',
    firefliesActionItems: transcript.summary?.action_items || '',
    receivedAt: event.receivedAt,
    clientReferenceId: event.clientReferenceId || ''
  }}];
}

// Manual chat test path.
const chatText = payload.chatInput ?? payload.text ?? payload.message;
if (typeof chatText !== 'string' || chatText.trim().length < 20) {
  throw new Error('For a manual test, send a chat message containing the meeting transcript (at least 20 characters).');
}
const now = new Date();
const manualId = `manual-${now.getTime()}`;
return [{ json: {
  meetingId: manualId,
  transcriptId: manualId,
  meetingTitle: 'Manual Chat Test',
  meetingDate: now.toISOString(),
  transcript: chatText.trim(),
  source: 'Manual Chat Test',
  summaryOverview: '',
  firefliesActionItems: '',
  receivedAt: now.toISOString(),
  clientReferenceId: ''
}}];

