// Parse AI output, validate fields, and create one row per task.
const content = $json.choices?.[0]?.message?.content;
if (!content) throw new Error('AI response did not contain choices[0].message.content.');
let parsed;
try { parsed = JSON.parse(content); } catch (e) { throw new Error('AI returned invalid JSON: ' + e.message); }
if (!Array.isArray(parsed.tasks)) throw new Error('AI response is missing the tasks array.');
const source = $('Normalize Retell Input').isExecuted ? $('Normalize Retell Input').first().json : $('Normalize Meeting Input').first().json;
if (parsed.tasks.length === 0) return [{ json: {
  noTasksFound: true,
  meetingId: source.meetingId,
  meetingTitle: source.meetingTitle,
  meetingSummary: parsed.meetingSummary || 'No actionable tasks identified.'
} }];
return parsed.tasks.map((task, index) => {
  const title = String(task.title || '').trim();
  const evidence = String(task.commitmentEvidence || '').trim();
  if (!title || !evidence) throw new Error(`Task ${index + 1} is missing a title or evidence excerpt; refusing to add unsupported task.`);
  const priority = ['Low', 'Medium', 'High', 'Unknown'].includes(task.priority) ? task.priority : 'Unknown';
  const confidence = ['High', 'Medium', 'Low'].includes(task.confidence) ? task.confidence : 'Low';
  const dueDate = /^\d{4}-\d{2}-\d{2}$/.test(String(task.dueDate || '')) ? task.dueDate : '';
  return { json: {
    noTasksFound: false,
    taskId: `${source.meetingId}-${index + 1}`,
    meetingId: source.meetingId,
    meetingTitle: source.meetingTitle,
    meetingDate: source.meetingDate,
    transcriptId: source.transcriptId,
    transcriptSource: source.source || 'Unknown',
    meetingSummary: parsed.meetingSummary || '',
    title,
    description: String(task.description || ''),
    owner: String(task.owner || ''),
    dueDate,
    priority,
    estimatedEffort: String(task.estimatedEffort || 'Unknown'),
    commitmentEvidence: evidence,
    confidence,
    reviewStatus: 'Pending Review',
    taskStatus: 'Not Started',
    reviewNotes: '',
    createdAt: new Date().toISOString()
  }};
});

// Mark meeting processed only after the Google Sheets append succeeded.
const rows = $input.all();
const store = $getWorkflowStaticData('global');
store.processedMeetings = store.processedMeetings || {};
const meetingId = $('Prepare Review Queue Rows').first().json.meetingId;
store.processedMeetings[meetingId] = { processedAt: new Date().toISOString() };
return rows;

